\title{Universality of the Cubic Spectral-Gap Exponent\\ for Weighted Swap Chains}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\maketitle

\begin{abstract}
Local ``swap'' chains --- reversible Markov chains that reconfigure combinatorial
objects by elementary moves --- are governed in their mixing speed by the
\emph{spectral gap} $\gamma$, the smallest non-trivial value of the Rayleigh
quotient $E(f)/V(f)$ of the associated Dirichlet form. We prove two structural
theorems that together explain, and cleanly separate, the two ingredients of the
gap's scaling law $\gamma \asymp \text{const}\cdot n^{-3}$ observed for
one-dimensional swap chains. First, a \emph{universality principle}: on an
arbitrary finite state space carrying non-negative conductances, any non-constant
test function whose Dirichlet energy grows at most linearly ($\le c_e n$) and
whose variation grows at least quartically ($\ge c_v n^4$) certifies a cubic gap
upper bound $\gamma \le (c_e/c_v)\,n^{-3}$; the exponent $3 = 4-1$ is a difference
of the two growth rates and is independent of the underlying combinatorial family.
Second, a \emph{conductance-scaling principle}: for the conductance-weighted path
of $n$ sites with edge weight $c>0$, the position statistic has Dirichlet energy
exactly $2c(n-1)$, variation exactly $n^2(n^2-1)/6$, and Rayleigh quotient exactly
$12c/(n^2(n+1))$, lying in the window $[6c\,n^{-3},\,12c\,n^{-3}]$; hence the
exponent $-3$ is independent of $c$ while the leading constant is strictly
increasing in $c$. Modelling a topological genus $g$ by a strictly decreasing,
strictly positive conductance $c(g)=1/(g+1)$ yields a family of gap upper bounds
$\gamma_{n,g}\le 12\,c(g)\,n^{-3}$ whose leading constant is strictly decreasing
in the genus while the cubic exponent is invariant.
\end{abstract}

\noindent\textbf{Keywords.} spectral gap, Rayleigh quotient, Dirichlet energy,
swap chain, mixing time, conductance, chord diagram, genus, universality.

\section{Introduction}

\subsection{Swap chains and their mixing speed}
A \emph{swap chain} on a finite combinatorial family reconfigures its objects by
local moves --- transpositions of adjacent tokens, exchanges of chord endpoints,
and the like. Such chains are the workhorses of combinatorial sampling and appear
throughout statistical mechanics, randomized algorithms, and the study of random
combinatorial structures. The central quantitative question about any such chain
is its \emph{mixing time}. For a reversible chain the mixing time is controlled up
to logarithmic factors by the reciprocal of the \emph{spectral gap} $\gamma$, the
smallest non-trivial eigenvalue of the normalized Laplacian, which admits a
variational characterization as an infimum of Rayleigh quotients.

\subsection{The one-dimensional prototype and its cubic law}
A recurring phenomenon is that one-dimensional swap chains --- those whose
essential geometry is a path --- exhibit a spectral gap of cubic order,
$\gamma \asymp n^{-3}$. On the path prototype the \emph{position statistic}
$f(i)=i$ has Dirichlet energy $\Theta(n)$ and variation $\Theta(n^4)$, so its
Rayleigh quotient is $\Theta(n^{-3})$. This paper elevates two consequences of
that observation to theorems: (i) the cubic exponent is \emph{universal}, a
property of the energy-to-variation growth profile alone; and (ii) introducing a
tunable \emph{conductance} --- the algebraic shadow of fixing a topological genus
--- moves the leading constant strictly monotonically while leaving the exponent
invariant.

\section{Setup and notation}
Throughout, $V$ is a finite set of states and $|V|$ its cardinality. A
\emph{conductance} is a function $Q\colon V\times V\to\RR_{\ge0}$ (symmetric in
the reversible setting). A \emph{test function} is any $f\colon V\to\RR$; it is
\emph{non-constant} if $f(x)\ne f(y)$ for some $x,y$.

\section{A finite-state Rayleigh calculus}

\begin{definition}[Dirichlet energy]
For a conductance $Q$ and test function $f$,
\[ E(f) = \dir_Q(f) = \sum_{x\in V}\sum_{y\in V} Q(x,y)\,\bigl(f(x)-f(y)\bigr)^2. \]
\end{definition}

\begin{definition}[Variation]
\[ V(f) = \vr(f) = \sum_{x\in V}\sum_{y\in V}\bigl(f(x)-f(y)\bigr)^2
        = 2\Bigl(|V|\sum_x f(x)^2 - \bigl(\textstyle\sum_x f(x)\bigr)^2\Bigr)
        = 2\,|V|\,\Var_{\mathrm{unif}}(f). \]
\end{definition}

\begin{definition}[Rayleigh quotient and gap]
For non-constant $f$, $\Ray_Q(f) = E(f)/V(f)$, and
\[ \gamma(Q) = \inf\{\Ray_Q(f) : f \text{ non-constant}\}. \]
\end{definition}

\begin{lemma}[Basic positivity]\label{lem:pos}
For every non-negative conductance $Q$ and test function $f$:
(1) $E(f)\ge0$; (2) $V(f)\ge0$, with $V(f)>0$ iff $f$ is non-constant;
(3) $\Ray_Q(f)\ge0$ and $\gamma(Q)\ge0$.
\end{lemma}
\begin{proof}
(1) Each summand is a product of non-negatives. (2) Each summand is non-negative;
a pair with $f(x_0)\ne f(y_0)$ contributes a strictly positive term, and if $f$ is
constant all terms vanish. (3) A non-negative divided by a positive is
non-negative, and an infimum of non-negatives is non-negative.
\end{proof}

\begin{lemma}[The Rayleigh engine]\label{lem:engine}
For every non-negative conductance $Q$ and non-constant $f$,
$\gamma(Q)\le \Ray_Q(f)$.
\end{lemma}
\begin{proof}
$\Ray_Q(f)$ lies in the set whose infimum defines $\gamma(Q)$, and that set is
bounded below by $0$ by Lemma~\ref{lem:pos}; hence its infimum is at most
$\Ray_Q(f)$.
\end{proof}

\begin{lemma}[Energy scales with conductance]\label{lem:smul}
For a scalar $c$, $\dir_{cQ}(f) = c\,\dir_Q(f)$.
\end{lemma}

\section{Universality of the cubic exponent}

\begin{theorem}[Universality, quotient form]\label{thm:uniq}
If $Q\ge0$ and $E(f)\le A$, $B\le V(f)$ with $B>0$, then $\Ray_Q(f)\le A/B$.
\end{theorem}
\begin{proof}
Since $B>0$ and $B\le V(f)$, we have $V(f)>0$, so $\Ray_Q(f)=E(f)/V(f)$ is
well defined and non-negative. Monotonicity of division gives
$E(f)/V(f)\le A/V(f)\le A/B$.
\end{proof}

\begin{theorem}[Universality, gap form]\label{thm:unig}
Under the hypotheses of Theorem~\ref{thm:uniq} with $f$ non-constant,
$\gamma(Q)\le A/B$.
\end{theorem}
\begin{proof}
Combine Lemma~\ref{lem:engine} and Theorem~\ref{thm:uniq}.
\end{proof}

\begin{theorem}[The cubic exponent is universal]\label{thm:cubic}
Let $Q\ge0$ on a finite state space and $f$ non-constant. If there are
$c_e\ge0$, $c_v>0$, $n>0$ with $E(f)\le c_e n$ and $c_v n^4\le V(f)$, then
\[ \gamma(Q) \le \frac{c_e}{c_v}\,n^{-3}. \]
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:unig} with $A=c_e n$ and $B=c_v n^4>0$ to get
$\gamma(Q)\le (c_e n)/(c_v n^4) = (c_e/c_v)\,n^{1-4} = (c_e/c_v)\,n^{-3}$.
\end{proof}

The exponent $-3$ arises purely as $1-4$: the difference between the linear growth
of the energy and the quartic growth of the variation. No property of the
combinatorial objects enters.

\section{The conductance-weighted path}

\begin{definition}[Conductance-weighted path]
For $c\in\RR$, $n\in\NN$, the weighted-path conductance on $\{0,\dots,n-1\}$ is
$Q_c(x,y)=c$ if $|x-y|=1$ and $0$ otherwise. Setting $c=1$ recovers the
unit-weight nearest-neighbor swap graph.
\end{definition}

\begin{definition}[Position statistic]
$f(i)=i$ for $i\in\{0,\dots,n-1\}$: a monotone statistic changing by exactly one
unit per legal move.
\end{definition}

\begin{lemma}
For $c\ge0$ the weights $Q_c$ are non-negative, and for $n\ge2$ the position
statistic is non-constant.
\end{lemma}

\begin{theorem}[Weighted-path energy]\label{thm:energy}
For $n\ge1$, $E(f)=\dir_{Q_c}(f)=2c(n-1)$.
\end{theorem}
\begin{proof}
Across an edge $\{x,y\}$ with $|x-y|=1$ we have $(f(x)-f(y))^2=1$; all other pairs
contribute $0$. Each of the $n-1$ adjacent pairs is counted twice in the double
sum, each time with weight $c$, giving $2c(n-1)$.
\end{proof}

\begin{theorem}[Weighted-path variation]\label{thm:var}
For all $n$, $V(f)=\vr(f)=\dfrac{n^2(n^2-1)}{6}$, independent of $c$.
\end{theorem}
\begin{proof}
By the variance identity with $|V|=n$,
$V(f)=2\bigl(n\sum_{i=0}^{n-1}i^2-(\sum_{i=0}^{n-1}i)^2\bigr)$. Using
$\sum i=\tfrac{n(n-1)}{2}$ and $\sum i^2=\tfrac{n(n-1)(2n-1)}{6}$,
\[ V(f)=2\Bigl(\frac{n^2(n-1)(2n-1)}{6}-\frac{n^2(n-1)^2}{4}\Bigr)
      =\frac{n^2(n-1)(n+1)}{6}=\frac{n^2(n^2-1)}{6}. \]
\end{proof}

\begin{theorem}[Exact Rayleigh quotient]\label{thm:rq}
For $n\ge2$,
\[ \Ray_{Q_c}(f)=\frac{2c(n-1)}{n^2(n^2-1)/6}=\frac{12c}{n^2(n+1)}. \]
\end{theorem}
\begin{proof}
Divide Theorem~\ref{thm:energy} by Theorem~\ref{thm:var} and use
$n^2-1=(n-1)(n+1)$.
\end{proof}

\begin{theorem}[Cubic upper bound at fixed conductance]\label{thm:up}
For $c\ge0$, $n\ge2$, $\gamma(Q_c)\le 12c/n^3$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:engine} and Theorem~\ref{thm:rq},
$\gamma(Q_c)\le 12c/(n^2(n+1))$; since $n^2(n+1)\ge n^3$ and $c\ge0$, the bound
follows.
\end{proof}

\begin{theorem}[The exponent is exactly three]\label{thm:window}
For $c\ge0$, $n\ge2$,
\[ \frac{6c}{n^3}\le \Ray_{Q_c}(f)\le \frac{12c}{n^3}. \]
\end{theorem}
\begin{proof}
Since $n\ge2$, $n^3\le n^2(n+1)\le 2n^3$. Substituting into
$\Ray_{Q_c}(f)=12c/(n^2(n+1))$ with $c\ge0$ gives
$6c\,n^{-3}\le \Ray_{Q_c}(f)\le 12c\,n^{-3}$. Both endpoints carry the exponent
$-3$.
\end{proof}

\begin{theorem}[The constant carries the conductance dependence]\label{thm:mono}
For fixed $n\ge2$, if $c_1<c_2$ then $\Ray_{Q_{c_1}}(f)<\Ray_{Q_{c_2}}(f)$.
\end{theorem}
\begin{proof}
Both quotients equal $12c/(n^2(n+1))$ with the same positive denominator, so
$c\mapsto\Ray_{Q_c}(f)$ is strictly increasing.
\end{proof}

\begin{remark}[Boundary case]
At $c=0$ the chain has no edges, the energy vanishes, and $\Ray_{Q_0}(f)=0$; the
strict statements therefore require positive conductance.
\end{remark}

\section{Modelling genus through a decreasing conductance}

The motivating application is the fixed-genus chord-swap chain, where one shuffles
chord diagrams of a prescribed topological genus $g$. The guiding principle is
that fixing the genus acts like fixing an effective conductance $c(g)$: a higher
genus imposes more topological obstructions per swap, hence a lower effective
conductance.

\begin{definition}[Genus conductance]
$c(g)=\dfrac{1}{g+1}$, for $g\in\NN$.
\end{definition}

\begin{lemma}\label{lem:genus}
$c(g)>0$ for every $g$, and $c$ is strictly decreasing: $g_1<g_2\Rightarrow
c(g_2)<c(g_1)$.
\end{lemma}
\begin{proof}
Positivity is immediate; and $g_1<g_2$ gives $g_1+1<g_2+1$, on which $t\mapsto1/t$
is strictly decreasing.
\end{proof}

\begin{theorem}[Genus enters only through the constant]\label{thm:genus}
With genus modelled by $c(g)$, for every $n\ge2$,
\[ \gamma\bigl(Q_{c(g)}\bigr)\le \frac{12\,c(g)}{n^3}, \]
and $12\,c(g)$ is strictly positive and strictly decreasing in $g$: if $g_1<g_2$
then $0<12\,c(g_2)<12\,c(g_1)$. The exponent $-3$ is independent of $g$.
\end{theorem}
\begin{proof}
The bound is Theorem~\ref{thm:up} with $c=c(g)\ge0$. Strict positivity and strict
monotonicity of $12\,c(g)$ follow from Lemma~\ref{lem:genus} by scaling by $12$.
The exponent is $-3$ in every case.
\end{proof}

Combining Theorems~\ref{thm:window} and~\ref{thm:genus}, the family of gap bounds
is $\gamma_{n,g}\lesssim 12/((g+1)n^3)$, all genus dependence carried by the scalar
amplitude $12\,c(g)$ and none by the exponent.

\section{Applications and discussion}
The cubic law gives a sharp handle on relaxation times of one-dimensional swap
samplers: relaxation time scales as $n^3$. Theorem~\ref{thm:cubic} reframes the
upper-bound problem as the estimation of two growth rates, turning an eigenvalue
problem into a moment-fitting problem. The pairing of
Theorems~\ref{thm:window} and~\ref{thm:genus} quarantines all parameter dependence
in a single leading constant while the exponent remains universal --- the
combinatorial analogue of a universal critical exponent with a system-specific
amplitude.

\section{Future work}
\begin{itemize}[leftmargin=1.4em]
  \item \textbf{A genus-aware quartic-variance statistic on diagram space.}
  Exhibiting one monotone, bounded-step statistic on genus-$g$ diagrams with
  linear energy and quartic variation would deliver the cubic upper bound
  automatically via Theorem~\ref{thm:cubic}.
  \item \textbf{Effective conductance of a genus.} Whether the induced effective
  conductance is genuinely a strictly decreasing $c(g)$ with
  $\gamma_{n,g}=12\,c(g)\,n^{-3}(1+o(1))$ is a concrete, testable prediction.
  \item \textbf{Sharpness of the criterion.} Energy of order $n$ with variation of
  order $n^\beta$, $\beta\ne4$, should give a gap bound of order $n^{1-\beta}$;
  making this two-sided pins the cubic exponent to the quartic-variation profile.
  \item \textbf{Matching lower bounds.} A canonical-path / multicommodity-flow
  routing with congestion of order $n^3$ would yield a two-sided
  $\Theta(n^{-3})$ law.
\end{itemize}

\section{Conclusion}
We have separated the two ingredients of the cubic spectral-gap law. The exponent
$-3$ is universal --- a difference of the linear energy growth and the quartic
variation growth --- and holds on any finite state space admitting a statistic
with that profile. The constant carries all individuality: a tunable conductance
scales the leading amplitude strictly monotonically without touching the exponent,
and a genus-decreasing conductance yields a strictly decreasing, strictly positive
amplitude in front of the invariant cubic decay.

