from fractions import Fraction

def rq(n: int, c: Fraction) -> Fraction:
    return 12 * c / (Fraction(n) ** 2 * (n + 1))

def main() -> None:
    c = Fraction(1)
    print(f"{'n':>6} {'6c/n^3':>14} {'R(f)':>16} {'12c/n^3':>14} {'n^3*R':>10}")
    for n in (2, 5, 10, 50, 200, 1000, 5000):
        lo = 6 * c / Fraction(n) ** 3
        hi = 12 * c / Fraction(n) ** 3
        r = rq(n, c)
        assert lo <= r <= hi
        print(f"{n:>6} {float(lo):>14.3e} {float(r):>16.3e} "
              f"{float(hi):>14.3e} {float(Fraction(n)**3 * r):>10.5f}")
    print('n^3 * R(f) -> 12: exponent is exactly 3.')

if __name__ == '__main__':
    main()

from fractions import Fraction

def genus_conductance(g: int) -> Fraction:
    return Fraction(1, g + 1)

def main() -> None:
    n = 20
    prev = None
    print(f"{'g':>3} {'c(g)':>10} {'12 c(g)':>10} {'gap bound':>16}")
    for g in range(6):
        cg = genus_conductance(g)
        amp = 12 * cg
        bound = amp / Fraction(n) ** 3
        if prev is not None:
            assert 0 < amp < prev
        prev = amp
        print(f"{g:>3} {float(cg):>10.5f} {float(amp):>10.5f} {float(bound):>16.3e}")
    print('Amplitude strictly decreasing; exponent -3 invariant.')

if __name__ == '__main__':
    main()
